from research_helpers import source, assessment, record, scope, evidence, decision, write_batch

refs=[
 ('atomic','Atomic Heart','Wikipedia contributors','https://en.wikipedia.org/wiki/Atomic_Heart','Kollektiv 1.0 coordinates robot labor; the new neuroconnector/post-labor rollout is prospective and the facility suffers a lethal crisis.','Existing robotic output is distinguished from the planned complete post-labor order; no ordinary household access rules are supplied.'),
 ('charles','Atomic Heart endings','Atomic Heart Wiki contributors','https://atomicheart.fandom.com/wiki/Atomic_Heart','Different closing choices change CHAR-les/Sechenov’s immediate fate and plans.','The close of the confrontation does not show a settled CHAR-les-administered material economy; copied Wikipedia mirrors were not independent support.'),
 ('industria','INDUSTRIA','TV Tropes contributors','https://tvtropes.org/pmwiki/pmwiki.php/VideoGame/INDUSTRIA','Hakavik becomes a depopulated hostile robot environment after the ATLAS disaster.','Secondary plot account; sequel release speculation is not used, and destruction is not human leisure.'),
 ('uncertain','The Uncertain: Last Quiet Day official description','ComonGames on Steam','https://store.steampowered.com/app/406970/The_Uncertain%3A%20Last%20Quiet%20Day/','An engineering robot investigates the supposedly vanished human species.','The opening extinction premise is not proof of every later revelation; no unified supported living population is established here.'),
 ('machinarium','Machinarium official description','Amanita Design','https://amanita-design.net/games/machinarium.html','An exiled robot solves problems, rescues another robot and confronts a criminal group in a robot city.','The original game is used, not newly announced Machinarium 2; no automatic human provision is described.'),
 ('fall','The Fall review','Destructoid reviewer','https://www.destructoid.com/reviews/review-the-fall/','A suit intelligence seeks medical help while the Caretaker destroys humans and machines deemed defective.','Neither a nominal pilot nor a malfunctioning test facility establishes a supported resident population; no sequel plans are treated as events.'),
 ('scrap','Scrap Garden official description','Egidijus Bachur, Alexey Davydov / Flazm on Steam','https://store.steampowered.com/app/465760/Scrap_Garden/','Canny awakens among shut-down robots and undertakes restoration.','Inactive machines and a restoration quest are not a living human post-work support order.'),
 ('steamworld','SteamWorld Dig 1 and 2 retrospective','TheSixthAxis reviewer','https://www.thesixthaxis.com/2024/07/08/playback-steamworld-dig-1-2/','Robot mining drives Tumbleton’s economy; humans also persist underground as Shiners.','Useful robot mining is not automatically labor-free production; human survival is not erased by a generic robot-successor label.'),
 ('synthetic-dawn','Synthetic Dawn launch announcement','Paradox Interactive on Steam','https://store.steampowered.com/news/posts/?appids=281990&enddate=1506003351','The released DLC permits machine empires that keep organics, assimilate them, or exterminate them.','Official 2017 scenario context, not a claim to current numerical balance or identical outcomes in all playthroughs.'),
 ('species-rights','Species rights / Mandatory Pampering','Stellaris Wiki contributors via a public static mirror','https://agentmystia.github.io/StellarisWiki/Mandatory_Pampering.html','Indexed rights tables distinguish Bio-Trophy pampering from working machine/cyborg drones and exterminated undesirables.','A public indexed mirror, not direct access to the current official wiki; version-dependent numeric upkeep/output is not adopted. The official Civics open returned 401 and was respected.'),
 ('servitor-launch-report','Synthetic Dawn presentation report','Sufficient Velocity community report of the Paradox presentation','https://forums.sufficientvelocity.com/threads/stellaris-paradox-grand-strategy-in-space.21143/page-294','Bounded presentation notes quote Bio-Trophy loss of responsibility/agency and describe machines doing the important work while organics occupy sanctuaries.','A 2017 audience transcription, not direct video viewing; obsolete tiles, ratios and influence bonuses are not used.'),
 ('assimilator-jobs','Driven Assimilator job-priority discussion','Steam community contributors','https://steamcommunity.com/app/281990/discussions/0/1640926712949013016/','Players describe organic cyborgs doing real mining, generation and replication jobs.','Historical player report corroborates a work distinction; exact patch behavior and modifiers are not asserted as current.')
]
S=[source('src-b80-'+sid,title,author,url,'official_description_or_labeled_reference','Bounded public/indexed description or reference table',claim,limits) for sid,title,author,url,claim,limits in refs]
r=['src-b80-synthetic-dawn','src-b80-species-rights','src-b80-servitor-launch-report']
R=[record('stellaris-human-rogue-servitor','c0661','Stellaris — Human Bio-Trophies under Rogue Servitors','Stellaris','A modeled machine empire maintaining human organics under Mandatory Pampering',['game'],
 scope('Released Synthetic Dawn Rogue Servitor scenario; qualitative rules only','A functioning player-configured empire with supplied organic sanctuaries','Living human organic Bio-Trophies in the chosen configuration',['Machine drones as humans','Alien species silently added to the human denominator','Shortage or extermination states as identical provision','Obsolete launch-era numeric bonuses'],player_configurable=True,branch='Rogue Servitor empire with human organics and Mandatory Pampering'),
 'Rogue Servitors turn organic maintenance into the purpose of a machine economy. In this explicitly modeled human configuration, robots run production while human residents receive sanctuary life and the Mandatory Pampering standard. The material guarantee estimate is strong within a functioning, supplied empire; it is a rule-based arrangement rather than a claim that the player cannot cause shortages or lose a war. The sources describe the qualitative system across versions, while obsolete launch-era balance numbers are deliberately omitted.\n\nControl lies with the machine intelligence, which frees its charges from responsibility while also removing agency. Affection, high happiness and a species-rights interface weight do not establish human ownership of the productive system. A high nonworking estimate follows the explicitly pampered life and delegation of ordinary production, but remains broad because useful art, care or other cultural activity can continue. The game’s Unity output is not automatically either a real job or proof of pure idleness. Only the selected living human population forms the denominator; robot drones do not inflate it.',
 {'guarantees':-0.85,'control':-1,'nonworking':0.9},
 {'guarantees':assessment(-0.85,[-1,-0.5],'medium','Mandatory Pampering and supplied sanctuaries organize continuing support; the scope assumes a functioning economy, not immunity to player-induced shortages.',r),
  'control':assessment(-1,[-1,-0.9],'medium','Machine administration removes organic productive responsibility and agency; interface political weights are not human ownership.',r),
  'nonworking':assessment(0.9,[0.5,1],'low','Pampered organics delegate ordinary production, but useful chosen cultural activity may continue and Unity is an abstract resource, not a census.',r)},
 5,r,[evidence('The released scenario lets machines maintain organic Bio-Trophies under compulsory pampering without ordinary productive responsibility.',r,'Official DLC announcement; citizenship/living-standard tables and presentation notes','official_scenario_plus_labeled_secondary_rules')],
 ['A player-configured human case, not a single fixed canonical civilization.', 'Qualitative rules only; no current patch-specific numerical claims.', 'Unity does not determine useful-work participation.', 'Supply failures and other organic statuses are separate modeled states.'])]
rows=[
 ('c0653','needs_evidence',['atomic'],'Existing robot labor and a planned post-labor rollout do not establish ordinary material allocation at Facility 3826.','An advanced research workplace and the promised Kollektiv 2.0 future remain distinct from a verified implemented support economy.'),
 ('c0654','needs_evidence',['charles','atomic'],'CHAR-les’s closing takeover/intent does not depict a settled post-work population.','Immediate control of the project cannot supply missing future food, shelter, rights or participation rules.'),
 ('c0655','boundary_case',['industria'],'ATLAS’s depopulated hostile robot city is not a supported living human society.','Survival and destruction do not turn vanished residents into nonworkers.'),
 ('c0656','needs_evidence',['uncertain'],'The robot-survivor premise does not establish an applicable active population and its work-independent material access.','An engineering robot’s investigation and a supposed human extinction require more than the premise to define a qualifying economy.'),
 ('c0657','boundary_case',['machinarium'],'The original robot city does not establish a supported human-person post-work economy.','Robot relationships and a rescue plot do not provide ordinary automatic allocation or a justified human participation scope.'),
 ('c0658','boundary_case',['fall'],'Caretaker testing and lethal defect classification do not establish a supported resident post-work community.','A suit intelligence seeking treatment is not proof of an active human pilot or general material provision.'),
 ('c0659','boundary_case',['scrap'],'A restoration quest among shut-down robots is not a living human post-work population.','Inactive machines and vanished humans cannot supply a leisure denominator.'),
 ('c0660','boundary_case',['steamworld'],'SteamWorld’s mining economy involves real robot work and surviving human Shiners.','Mechanical bodies do not make labor automatic for the people doing it, and human disappearance is not universal.'),
 ('c0662','boundary_case',['synthetic-dawn','species-rights'],'Determined Exterminators eliminate organics rather than maintain them as a living post-work population.','Purging and machine production do not mean humans enjoy complete leisure.'),
 ('c0663','boundary_case',['species-rights','assimilator-jobs'],'Driven Assimilator cyborgs perform real productive drone jobs.','Assimilated human-derived bodies remain workers; integration is distinct from the Servitor sanctuary arrangement.'),
 ('c0664','needs_evidence',['species-rights'],'Synthetic ascension alone does not specify living standards or ordinary productive access.','A human-derived synthetic citizen configuration needs its actual rights and allocation settings; a mechanical body does not supply them.')
]
D=[decision(cid,status,reason,['src-b80-'+s for s in ss],analysis=analysis,follow_up='Save the short disposition and continue; no full lore or patch reconstruction to rescue a body/AI-only lead.') for cid,status,ss,reason,analysis in rows]
D.append(decision('c0661','included','The released modeled civic explicitly maintains living human organics through machine provision and Mandatory Pampering.',r,society_id=R[0]['id']))
D.sort(key=lambda x:x['candidate_id'])
write_batch(80,[f'c{i:04}' for i in range(653,665)],S,R,D,[
 'Twelve fast decisions and one explicitly configurable Rogue Servitor record. No complete game, novel or patch-history read.',
 'Official Synthetic Dawn release context corroborates clearly labeled public rules references. Current official wiki access failed and was not bypassed.',
 'No obsolete launch-era balance numbers or new sequel promises were adopted. Machine workers, biological cyborg workers and maintained organics remain different cases.',
 'Atomic Heart’s promised full post-labor rollout and closing control struggle do not establish a settled future economy.',
 'The Uncertain’s advertised extinction is treated as a premise, and SteamWorld’s surviving human Shiners are not erased.'
])
